 "new_string": "def transform(grid):
    """Draw marker-to-marker rays and recolor every hit color-2 object."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marked_rows = [r for r in range(h) if sum(v == 1 for v in grid[r]) >= 2]
    marked_cols = [c for c in range(w) if sum(grid[r][c] == 1 for r in range(h)) >= 2]
    rays = {(r, c) for r in marked_rows for c in range(w)}
    rays.update((r, c) for c in marked_cols for r in range(h))

    # Any 2-component hit by a ray changes entirely to color 1.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            component = []
            seen.add((r, c))
            while stack:
                x, y = stack.pop()
                component.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
